76:       // [link](  <href>  "title"  )
77:       //                         ^^ skipping these spaces
78:       for (; pos < max; pos++) {
79:         code = state.src.charCodeAt(pos);
80:         if (code !== 0x20 && code !== 0x0A) { break; }
81:       }
82:     } else {
83:       title = '';
84:     }
85: 
86:     if (pos >= max || state.src.charCodeAt(pos) !== 0x29/* ) */) {
87:       state.pos = oldPos;
88:       return false;
89:     }
90:     pos++;
91:   } else {
92:     //
93:     // Link reference
94:     //
95:     if (typeof state.env.references === 'undefined') { return false; }
96: 
97:     // [foo]  [bar]
98:     //      ^^ optional whitespace (can include newlines)
99:     for (; pos < max; pos++) {
100:       code = state.src.charCodeAt(pos);
101:       if (code !== 0x20 && code !== 0x0A) { break; }
102:     }
103: 
104:     if (pos < max && state.src.charCodeAt(pos) === 0x5B/* [ */) {
105:       start = pos + 1;
106:       pos = parseLinkLabel(state, pos);
107:       if (pos >= 0) {
108:         label = state.src.slice(start, pos++);
109:       } else {
110:         pos = labelEnd + 1;
111:       }
112:     } else {
113:       pos = labelEnd + 1;
114:     }
115: 
116:     // covers label === '' and label === undefined
117:     // (collapsed reference link and shortcut reference link respectively)
118:     if (!label) { label = state.src.slice(labelStart, labelEnd); }
119: 
120:     ref = state.env.references[normalizeReference(label)];
121:     if (!ref) {
122:       state.pos = oldPos;
123:       return false;
124:     }
125:     href = ref.href;
126:     title = ref.title;
127:   }
128: 
129:   //
130:   // We found the end of the link, and know for a fact it's a valid link;
131:   // so all that's left to do is to call tokenizer.
132:   //
133:   if (!silent) {
134:     state.pos = labelStart;
135:     state.posMax = labelEnd;
136: 
137:     token        = state.push('link_open', 'a', 1);
138:     token.attrs  = attrs = [ [ 'href', href ] ];
139:     if (title) {
140:       attrs.push([ 'title', title ]);
141:     }
142: 
143:     state.md.inline.tokenize(state);
144: 
145:     token        = state.push('link_close', 'a', -1);
146:   }
147: 
148:   state.pos = pos;
149:   state.posMax = max;
150:   return true;
151: };
